fn choose_odd() {
    // Initialize the accumulator to 5.
    let mut acc: u64 = 5;

    // First counted loop: i goes from 0 up to (but not including) 10.
    // Each iteration increments the accumulator by 1.
    let mut i: u64 = 0;
    while i < 10 {
        acc += 1;
        i += 1;
    }

    // Reset the loop index and repeat the same loop.
    i = 0;
    while i < 10 {
        acc += 1;
        i += 1;
    }

    // After two loops of 10 iterations each, acc == 5 + 10 + 10 == 25.
    assert_eq!(acc, 25);
}